<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/bootstrap.php';
use School\Core\SchoolAuth;
use School\Core\SchoolDatabase;
SchoolAuth::requireLogin();$user=SchoolAuth::user();$role=school_current_role($user);$pdo=SchoolDatabase::connection();
if($role==='parent_guardian'&&SchoolAuth::hasPermission('portal.child')){$q=$pdo->prepare("SELECT s.id,s.admission_number,s.full_name,s.gender,s.admission_date,sg.relationship,c.name class_name,y.name year_name FROM student_guardians sg JOIN guardians g ON g.id=sg.guardian_id JOIN students s ON s.id=sg.student_id LEFT JOIN enrollments en ON en.student_id=s.id AND en.status='active' LEFT JOIN class_groups c ON c.id=en.class_group_id LEFT JOIN academic_years y ON y.id=en.academic_year_id WHERE g.user_id=:user AND sg.verification_status='verified' AND sg.ended_at IS NULL ORDER BY s.full_name");$q->execute(['user'=>(int)$user['id']]);$children=$q->fetchAll();}
elseif($role==='student'&&SchoolAuth::hasPermission('portal.self')){$q=$pdo->prepare("SELECT s.id,s.admission_number,s.full_name,s.gender,s.admission_date,'' relationship,c.name class_name,y.name year_name FROM students s LEFT JOIN enrollments en ON en.student_id=s.id AND en.status='active' LEFT JOIN class_groups c ON c.id=en.class_group_id LEFT JOIN academic_years y ON y.id=en.academic_year_id WHERE s.user_id=:user");$q->execute(['user'=>(int)$user['id']]);$children=$q->fetchAll();}
else{http_response_code(403);exit('Student portal access is not permitted.');}
$schoolName=(string)($pdo->query('SELECT name FROM school_profile ORDER BY id LIMIT 1')->fetchColumn()?:'School Management');$schoolRole=$role;$pageTitle=$role==='student'?'My school record':'My children';require dirname(__DIR__).'/includes/header.php';
?>
<div class="page-head"><div><h4><?= $role==='student'?'My school record':'My children' ?></h4><p>Academic results, attendance and fee statements available for records linked to your account.</p></div></div>
<div class="row g-3"><?php foreach($children as $child): ?><div class="col-xl-6"><div class="card h-100"><div class="card-header d-flex justify-content-between align-items-center"><span class="card-title-sm"><i class="bi bi-person-vcard me-1"></i><?= e($child['full_name']) ?></span><span class="badge bg-light text-dark"><?= e($child['admission_number']) ?></span></div><div class="card-body"><div class="row g-2 small"><div class="col-6"><span class="text-muted">Class</span><div class="fw-semibold"><?= e($child['class_name']??'Not enrolled') ?></div></div><div class="col-6"><span class="text-muted">Academic year</span><div class="fw-semibold"><?= e($child['year_name']??'—') ?></div></div><?php if($role==='parent_guardian'): ?><div class="col-12"><span class="text-muted">Relationship</span><div class="fw-semibold"><?= e($child['relationship']) ?></div></div><?php endif; ?></div><div class="mt-3"><a class="btn btn-primary btn-sm" href="<?= SCHOOL_BASE_URL ?>portal/child.php?id=<?= (int)$child['id'] ?>"><i class="bi bi-eye me-1"></i>View school record</a></div></div></div></div><?php endforeach; ?><?php if(!$children): ?><div class="col-12"><div class="card"><div class="card-body text-center text-muted py-5"><i class="bi bi-person-exclamation fs-2 d-block mb-2"></i>No verified student relationship is linked to this account yet. Contact the school office.</div></div></div><?php endif; ?></div>
<?php require dirname(__DIR__).'/includes/footer.php'; ?>
